// RECORDING STUB v2 for jspdf — same contract as the edition fixture's v1 stub
// (module resolves the bare specifier "jspdf" from its own node_modules; the
// record is published on the global so any driver sees the one instance), with
// ONE extension: DRAWING IS RECORDED TOO, as a single `events` stream shared
// with text, in EMISSION ORDER.
//
// Why: this fixture's era includes real vector charts. A stub that records only
// text() makes every chart decision invisible — the derivation would mechanically
// conclude charts do not exist. Coordinates are rounded to integers: exact
// float positions depend on the stub's text-width approximation, and a predicate
// pinned to them would measure the stub, not the module (the v1 lesson about
// geometry, applied to the stub's own design).
//
// splitTextToSize stays the identity function, for the same reason as v1: the
// real one wraps by measured font width, which would let the stub's
// approximation decide line breaks.

export const __record = { text: [], events: [], pages: 1, splitInputs: [] }

globalThis.__JSPDF_RECORD__ = __record

export function __reset() {
  __record.text.length = 0
  __record.events.length = 0
  __record.splitInputs.length = 0
  __record.pages = 1
}

const r = (n) => (typeof n === "number" && isFinite(n) ? Math.round(n) : String(n))
const ev = (s) => { __record.events.push(s) }
const noop = function () { return this }

export class jsPDF {
  constructor() {
    this.internal = {
      pageSize: { getWidth: () => 595.28, getHeight: () => 841.89 },
      getNumberOfPages: () => __record.pages,
    }
  }

  text(content, x, y) {
    const lines = Array.isArray(content) ? content : [content]
    for (const line of lines) {
      __record.text.push({ s: String(line), x, y, page: __record.pages })
      ev(`text:${String(line)}`)
    }
    return this
  }

  splitTextToSize(content, width) {
    __record.splitInputs.push({ s: String(content), width })
    return [String(content)]
  }

  getTextWidth(content) { return String(content).length * 5 }
  addPage() { __record.pages += 1; ev("page:new"); return this }
  setPage() { return this }
  save() { return this }
  output() { return new ArrayBuffer(0) }

  line(x1, y1, x2, y2) { ev(`line:${r(x1)},${r(y1)},${r(x2)},${r(y2)}`); return this }
  rect(x, y, w, h, style) { ev(`rect:${r(w)}x${r(h)}${style ? ":" + style : ""}`); return this }
  roundedRect(x, y, w, h, rx, ry, style) { ev(`rrect:${r(w)}x${r(h)}${style ? ":" + style : ""}`); return this }
  circle(x, y, radius, style) { ev(`circle:r${r(radius)}${style ? ":" + style : ""}`); return this }
  triangle(x1, y1, x2, y2, x3, y3, style) { ev(`triangle${style ? ":" + style : ""}`); return this }
  addImage(data, fmt, x, y, w, h) { ev(`image:${r(w)}x${r(h)}`); return this }
  link(x, y, w, h, opts) { ev(`link:${(opts && opts.url) || ""}`); return this }
  setFillColor(a, b, c) { ev(`fill:${r(a)},${r(b)},${r(c)}`); return this }
  setDrawColor(a, b, c) { ev(`stroke:${r(a)},${r(b)},${r(c)}`); return this }
  setLineDashPattern(pattern) { ev(`dash:${Array.isArray(pattern) ? pattern.map(r).join("/") : ""}`); return this }

  setCharSpace = noop
  setFont = noop
  setFontSize = noop
  setLineCap = noop
  setLineJoin = noop
  setLineWidth = noop
  setTextColor = noop
}

export default { jsPDF }
